CREATE TABLE "audiocpp_settings" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "audiocpp_settings_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"enabled" boolean DEFAULT false NOT NULL,
	"binary_dir" text,
	"binary_variant" text,
	"release_tag" text,
	"port" integer DEFAULT 5002 NOT NULL,
	"models_dir" text,
	"backend" text,
	"device_index" integer,
	"threads" integer,
	"max_loaded_models" integer,
	"idle_unload_ms" integer,
	"subprocess_timeout_minutes" integer DEFAULT 30 NOT NULL,
	"config_hash" text,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL
);
